struct Shape {
    virtual ~Shape() {}
    virtual int area() const = 0;
};

struct Rect : Shape {
    int w, h;
    static int destroyed;
    Rect(int w, int h) : w(w), h(h) {}
    ~Rect() override { destroyed += 1; }
    int area() const override { return w * h; }
};
int Rect::destroyed = 0;

struct Square : Rect {
    explicit Square(int side) : Rect(side, side) {}
    int area() const override { return Rect::area() + 1; }
};

template <typename T> T twice(T value) { return value + value; }

struct Counter {
    int value;
    Counter() : value(42) {}
};
Counter counter;

struct Accumulator {
    int value;
    Accumulator(int start) : value(start * 2) {}
};
Accumulator accumulator(counter.value + 1);

__attribute__((noinline)) int total(const Shape &shape) { return shape.area(); }

int main() {
    Rect rect(3, 4);
    Square square(5);
    int sum = total(rect) + total(square) + twice(counter.value) + twice<short>(7) + accumulator.value;
    {
        Rect inner(1, 1);
        sum += inner.area();
    }
    return sum + Rect::destroyed;
}
